key q; integer line = 0;
default { state_entry() { llOwnerSay((string)llGetInventoryNumber(INVENTORY_ALL) + " items, first " + llGetInventoryName(INVENTORY_NOTECARD, 0)); q = llGetNotecardLine("config", line); }
 dataserver(key id, string data) { if (id != q) return; if (data == EOF) { llOwnerSay("end"); return; } llOwnerSay("line " + data); q = llGetNotecardLine("config", ++line); } }

default { state_entry() {
  llSetScale(<1, 2, 0.5>);
  llOwnerSay((string)llGetMass() + " " + (string)llGetVel());
  llOwnerSay(llGetLinkName(LINK_THIS) + " " + (string)llGetLinkKey(2));
  llOwnerSay(llList2CSV([llGetObjectPermMask(MASK_OWNER), llGetObjectPermMask(MASK_NEXT), llGetInventoryPermMask("Script", MASK_GROUP)]));
  llOwnerSay(llList2CSV([llGetCreator(), llGetUsername(llGetOwner()), llSameGroup(NULL_KEY), llSameGroup(llGetKey())]));
  llOwnerSay(llList2CSV(llGetObjectDetails(llGetKey(), [OBJECT_NAME, OBJECT_OWNER, OBJECT_PRIM_COUNT, OBJECT_TOTAL_INVENTORY_COUNT, OBJECT_MATERIAL, OBJECT_HEALTH, 999])));
  llOwnerSay((string)llGetListLength(llGetObjectDetails(NULL_KEY, [OBJECT_NAME])));
} }

scripts.source:
default {
  touch_start(integer n) {
    integer link = llDetectedLinkNumber(0);
    llOwnerSay("touched link " + (string)link);
    if (link == 2) { llSetScriptState("helper", FALSE); llOwnerSay("helper " + (string)llGetScriptState("helper")); }
    else { llSetScriptState("helper", TRUE); llResetOtherScript("helper"); }
  }
  changed(integer c) { llDie(); }
}

integer touches;
default {
  touch_start(integer n) { touches = 0; llOwnerSay("start " + llDetectedName(0)); }
  touch(integer n) { ++touches; }
  touch_end(integer n) { llOwnerSay("end after " + (string)touches + " touch events, link " + (string)llDetectedLinkNumber(0)); }
}

default {
  touch_end(integer n) { llOwnerSay("child let go " + (string)n + " " + llDetectedName(0)); }
}

request.source:
key asked;
default {
  state_entry() {
    llOwnerSay(llGetRegionName() + " " + (string)llGetRegionCorner() + " ground " + (string)llGround(ZERO_VECTOR) + " water " + (string)llWater(ZERO_VECTOR));
    llOwnerSay(llGetDate() + " " + llGetTimestamp() + " " + (string)llGetWallclock() + " " + (string)llGetTimeOfDay() + " " + (string)llGetSunDirection());
    llOwnerSay(llList2CSV(llGetAgentList(AGENT_LIST_REGION, [])) + " " + (string)llGetAgentSize("11111111-2222-3333-4444-555555555555"));
    asked = llRequestAgentData("11111111-2222-3333-4444-555555555555", DATA_NAME);
    llSetTimerEvent(1.5);
  }
  dataserver(key id, string data) { llOwnerSay((string)(id == asked) + " " + data); }
  timer() {
    llSetTimerEvent(0);
    llOwnerSay(llGetTimestamp() + " " + (string)llGetWallclock() + " " + (string)llGetTimeOfDay() + " " + (string)llGetSunDirection());
  }
}

default {
  state_entry() { llRequestURL(); llSetTimerEvent(3); }
  http_request(key id, string method, string body) {
    if (method == URL_REQUEST_GRANTED) { llOwnerSay("url " + body + " free " + (string)llGetFreeURLs()); return; }
    llOwnerSay(method + " " + llGetHTTPHeader(id, "x-path-info") + "?" + llGetHTTPHeader(id, "x-query-string") + " " + body);
    llHTTPResponse(id, 200, "thanks");
  }
  money(key id, integer amount) { llOwnerSay("paid " + (string)amount); }
  timer() { llSetTimerEvent(0); llGetNextEmail("", ""); }
  email(string time, string address, string subject, string message, integer left) {
    llOwnerSay(time + " " + address + " " + subject + ": " + message + " (" + (string)left + " left)");
  }
}
